class Widget {
    int size_;
    int type_;
public:
    // Delegating Default Constructor
    Widget() : Widget(0, 1) {}

    // Parameterized Constructor (Initialization List Best Practice)
    Widget(int s, int t)
        : size_(s), type_(t) {}

    // Explicit Constructor (Prevents implicit conversion: Widget w = 5;)
    explicit Widget(int s)
        : Widget(s, 1) {}

    // `= default`: Compiler generated standard behavior
    Widget(const Widget&) = default;

    // `= delete`: Prevents unwanted object creation
    // Widget(int s, int t) = delete;
};

